description:
Do what a TCP receiver does with segments that arrive out of order, twice, or overlapping (lesson 1.04):

```cpp
class Receiver
{
public:
    explicit Receiver(std::uint32_t firstSeq);
    void segment(std::uint32_t seq, const std::string& data);
    std::string read();
    std::uint32_t ack() const;
    std::size_t buffered() const;
};
```

- The first byte of the stream has sequence number `firstSeq`; each byte after it has the next number. (Sequence numbers here do not wrap.)
- **segment** delivers bytes `seq` to `seq + data.size() - 1`. Bytes already delivered to the program are ignored; bytes beyond what is contiguous are **held**; when a gap is filled, everything now contiguous becomes readable. Overlapping segments carry the same bytes, so any copy of a byte will do.
- **read** returns all readable bytes, in order, and removes them.
- **ack** is the sequence number of the next byte expected: one past the last contiguous byte received.
- **buffered** counts bytes held beyond a gap.

starter.solution.cpp:
#include <cstdint>
#include <string>

class Receiver
{
public:
    explicit Receiver(std::uint32_t firstSeq) {}
    void segment(std::uint32_t seq, const std::string& data) {}
    std::string read() { return ""; }
    std::uint32_t ack() const { return 0; }
    std::size_t buffered() const { return 0; }
};

solution.solution.cpp:
#include <cstdint>
#include <map>
#include <string>

class Receiver
{
public:
    explicit Receiver(std::uint32_t firstSeq) : expected{ firstSeq } {}

    void segment(std::uint32_t seq, const std::string& data)
    {
        for (std::size_t i{ 0 }; i < data.size(); ++i)
        {
            const std::uint32_t s{ seq + static_cast<std::uint32_t>(i) };
            if (s >= expected) early.emplace(s, data[i]);
        }
        auto it{ early.find(expected) };
        while (it != early.end())
        {
            ready += it->second;
            early.erase(it);
            ++expected;
            it = early.find(expected);
        }
    }

    std::string read()
    {
        std::string out;
        out.swap(ready);
        return out;
    }

    std::uint32_t ack() const { return expected; }
    std::size_t buffered() const { return early.size(); }

private:
    std::uint32_t expected;
    std::map<std::uint32_t, char> early;
    std::string ready;
};

unitTests:
TEST("in order") {
    Receiver r{ 1000 };
    r.segment(1000, "hello ");
    r.segment(1006, "world");
    CHECK_EQ(r.ack(), 1011u);
    CHECK_EQ(r.read(), std::string("hello world"));
    CHECK_EQ(r.read(), std::string(""));
}
TEST("a gap holds back later data") {
    Receiver r{ 0 };
    r.segment(0, "abc");
    r.segment(6, "ghi");
    CHECK_EQ(r.read(), std::string("abc"));
    CHECK_EQ(r.ack(), 3u);
    CHECK_EQ(r.buffered(), 3u);
    r.segment(3, "def");
    CHECK_EQ(r.ack(), 9u);
    CHECK_EQ(r.read(), std::string("defghi"));
    CHECK_EQ(r.buffered(), 0u);
}
TEST("duplicates and overlaps") {
    Receiver r{ 50 };
    r.segment(50, "abcd");
    r.segment(50, "abcd");
    r.segment(52, "cdef");
    CHECK_EQ(r.read(), std::string("abcdef"));
    r.segment(40, "old data");
    CHECK_EQ(r.read(), std::string(""));
    CHECK_EQ(r.ack(), 56u);
}
TEST("many pieces in reverse") {
    Receiver r{ 7 };
    const std::string text{ "the quick brown fox" };
    for (std::size_t i{ text.size() }; i-- > 0;) r.segment(7 + static_cast<std::uint32_t>(i), std::string(1, text[i]));
    CHECK_EQ(r.read(), text);
}

